fn last[T](items: &Vec[T]) -> T {
  return items[items.len() - 1];
}

fn count_matching[T: Eq](items: &Vec[T], target: T) -> Int {
  var count = 0;
  for item in items {
    if item == target { count = count + 1; }
  }
  return count;
}

fn main() -> Int {
  let v = Vec[Int]();
  v.push(1); v.push(2); v.push(2); v.push(3);
  let l = last[Int](&v);
  let c = count_matching[Int](&v, 2);
  return c;
}
